<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?= e($invoice['number']) ?> · <?= e($seller['name']) ?></title><link rel="stylesheet" href="<?= e(asset_url('receipt.css')) ?>"><link rel="stylesheet" href="<?= e(asset_url('receipt-shell.css')) ?>"></head><body><?php require __DIR__.'/invoice-body.php'; ?><div class="bill-actions"><button id="print-bill">Print / Save PDF</button><?php if($receipt_download): ?><a href="<?= e($receipt_download) ?>" data-pdf-source="<?= e($receipt_back&&str_starts_with($requestPath,'/checkout/')?rtrim($requestPath,'/').'/':$requestPath) ?>" data-pdf-filename="<?= e(str_replace('/','-',$invoice['number']).'.pdf') ?>">Download PDF</a><?php endif; ?><a href="<?= e($receipt_back?:'/') ?>"><?= $receipt_back?'Back to order':'Home' ?></a><?php if($staffBill&&!$credit): ?><a href="/billing/new/?channel=<?= strtolower((string)($buyer['channel']??''))==='whatsapp'?'whatsapp':'manual' ?>">New booking</a><?php endif; ?></div><script src="<?= e(asset_url('print.js')) ?>" defer></script><script src="<?= e(asset_url('receipt-export.js')) ?>" defer></script></body></html>
